11	#[derive(Debug, thiserror::Error)]
12	pub enum Error {
13	    #[error(transparent)]
14	    Nom(#[from] nom::error::Error<String>),
15	    #[error("Dependency path '{0}' contains no '@'.")]
16	    MissingAt(String),
17	    #[error("Dependency path '{0}' has an empty version following '@'.")]
18	    MissingVersion(String),
19	}
