21	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
22	pub struct DepPath<'a> {
23	    // todo we possibly keep the full string here for 0-cost serialization
24	    pub name: &'a str,
25	    pub version: &'a str,
26	    pub host: Option<&'a str>,
27	    pub peer_suffix: Option<&'a str>,
28	}
29	
30	impl<'a> DepPath<'a> {
31	    pub fn new(name: &'a str, version: &'a str) -> Self {
32	        Self {
33	            name,
34	            version,
35	            host: None,
36	            peer_suffix: None,
37	        }
38	    }
39	
40	    pub fn parse(version: SupportedLockfileVersion, input: &'a str) -> Result<Self, Error> {
41	        match version {
42	            SupportedLockfileVersion::V7AndV9 => parse_dep_path_v9(input),
43	            SupportedLockfileVersion::V5 | SupportedLockfileVersion::V6 => {
44	                let (_, dep_path) = parse_dep_path(input).map_err(|e| e.to_owned()).finish()?;
45	                Ok(dep_path)
46	            }
47	        }
48	    }
49	
50	    pub fn with_host(mut self, host: Option<&'a str>) -> Self {
51	        self.host = host;
52	        self
53	    }
54	
55	    pub fn with_peer_suffix(mut self, peer_suffix: Option<&'a str>) -> Self {
56	        self.peer_suffix = peer_suffix;
57	        self
58	    }
59	
60	    pub fn patch_hash(&self) -> Option<&str> {
61	        self.peer_suffix.and_then(|s| {
62	            if s.starts_with('(') {
63	                let (_, suffixes) = parse_v6_suffixes(s).ok()?;
64	                suffixes.iter().find_map(|s| s.strip_prefix("patch_hash="))
65	            // Check if suffix is pre v6
66	            } else if let Some(idx) = s.find('_') {
67	                Some(&s[..idx])
68	            } else {
69	                // if a dependency just has a single suffix we can't tell if it's
70	                // a patch or peer hash return it in case it's a patch hash
71	                Some(s)
72	            }
73	        })
74	    }
75	}
