    /// Adds an injected `file:` package (identified by `key`) and all of its
    /// transitive dependencies to the pruned `packages` and `snapshots` maps.
    ///
    /// The injected package's snapshot lists its direct dependencies; for each
    /// one we construct the full package key and recursively pull in the
    /// corresponding `packages`/`snapshots` entries.
    fn add_injected_package(
        &self,
        key: &str,
        pruned_packages: &mut Packages,
        pruned_snapshots: &mut Option<Snapshots>,
    ) {
        let mut visited: HashSet<String> = HashSet::new();
        let mut queue: VecDeque<String> = VecDeque::new();

        visited.insert(key.to_string());
        queue.push_back(key.to_string());

        while let Some(current) = queue.pop_front() {
            // Include the package entry if one exists.
            if let Some(entry) = self.get_packages(&current) {
                pruned_packages
                    .entry(current.clone())
                    .or_insert_with(|| entry.clone());
            }

            // Include the snapshot entry if one exists.
            if let (Some(all_snapshots), Some(pruned)) =
                (self.snapshots.as_ref(), pruned_snapshots.as_mut())
            {
                if let Some(snapshot) = all_snapshots.get(&current) {
                    pruned
                        .entry(current.clone())
                        .or_insert_with(|| snapshot.clone());
                }
            }

            // Traverse the transitive dependencies of this package.
            if let Some(dependencies) = self.dependency_index.get(&current) {
                for (dep_name, dep_version) in dependencies {
                    let dep_key = self.format_key(dep_name, dep_version);
                    if visited.insert(dep_key.clone()) {
                        queue.push_back(dep_key);
                    }
                }
            }
